import json
import os
import boto3
s3 = boto3.client('s3')
sns = boto3.client('sns')

def move_objects_by_prefix(bucket: str, src_prefix: str, dst_prefix: str) -> dict:
    result = {'bucket': bucket, 'src_prefix': src_prefix, 'dst_prefix': dst_prefix, 'moved': [], 'failed': [], 'total_bytes': 0}
    if src_prefix == dst_prefix:
        result['error'] = 'source and destination are identical'
        return result
    paginator = s3.get_paginator('list_objects_v2')
    for page in paginator.paginate(Bucket=bucket, Prefix=src_prefix):
        for obj in page.get('Contents', []):
            key = obj['Key']
            new_key = dst_prefix + key[len(src_prefix):]
            try:
                s3.copy_object(Bucket=bucket, Key=new_key, CopySource={'Bucket': bucket, 'Key': key})
                s3.delete_object(Bucket=bucket, Key=key)
                result['moved'].append({'from': key, 'to': new_key})
                result['total_bytes'] += obj['Size']
            except Exception as e:
                result['failed'].append({'key': key, 'error': str(e)})
    topic_arn = os.environ.get('MOVE_NOTIFY_TOPIC_ARN')
    if topic_arn and result['moved']:
        try:
            sns.publish(
                TopicArn=topic_arn,
                Subject='S3 objects moved',
                Message=json.dumps({'bucket': bucket, 'moved': result['moved'], 'failed': result['failed']}),
            )
        except Exception as e:
            result['notify_error'] = str(e)
    result['count'] = len(result['moved'])
    return result
